// OpenBSD rasops_init picks by screen width: 32px glyphs past 3840, 16px
// past 1920, 12px past 960, 8px below that. Widest first, so the walk stops
// at the first face the display is wide enough for.
const struct console_font console_fonts[] = {
    {"Spleen 32x64", console_font_32x64, 32, 64, 4, 120 * 32},
    {"Spleen 16x32", console_font_16x32, 16, 32, 2, 120 * 16},
    {"Spleen 12x24", console_font_12x24, 12, 24, 2, 80 * 12 + 1},
    {"Spleen 8x16", console_font_8x16, 8, 16, 1, 0},
};

const uint console_font_count =
    sizeof(console_fonts) / sizeof(console_fonts[0]);
